CREATE TABLE `provider_adapter_health` (`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`adapter_version` VARCHAR(80) CHARACTER SET ascii NULL,`health_status` ENUM('ready','degraded','blocked') NOT NULL,`last_checked_at` DATETIME(3) NOT NULL,`last_latency_ms` INT UNSIGNED NULL,`last_error_code` VARCHAR(80) CHARACTER SET ascii NULL,`consecutive_failures` INT UNSIGNED NOT NULL,`version` INT UNSIGNED NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`provider_id`),KEY `idx_provider_adapter_health_status` (`health_status`,`updated_at`),CONSTRAINT `fk_provider_adapter_health_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `provider_adapter_health_versions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL,`snapshot_json` JSON NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`action` ENUM('checked') NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_provider_adapter_health_version` (`provider_id`,`version`),KEY `idx_provider_adapter_health_trace` (`trace_id`),CONSTRAINT `fk_provider_adapter_health_version_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_provider_adapter_health_version_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `provider_adapter_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`route` VARCHAR(180) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_version` INT UNSIGNED NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_provider_adapter_operation` (`actor_id`,`route`,`idempotency_key`),KEY `idx_provider_adapter_operation_trace` (`trace_id`),CONSTRAINT `fk_provider_adapter_operation_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),CONSTRAINT `fk_provider_adapter_operation_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
